  function scallop(cx,cy,rad,n,amp){
    let d='';
    for(let i=0;i<=n;i++){
      const a=i/n*Math.PI*2, x=cx+rad*Math.cos(a), y=cy+rad*Math.sin(a);
      if(!i){d+='M'+x.toFixed(1)+' '+y.toFixed(1);continue;}
      const m=(i-.5)/n*Math.PI*2;
      d+=' Q'+(cx+(rad+amp*2)*Math.cos(m)).toFixed(1)+' '+(cy+(rad+amp*2)*Math.sin(m)).toFixed(1)+' '+x.toFixed(1)+' '+y.toFixed(1);
    }
    return d+' Z';
  }
  function star(cx,cy,R,ri,n){
    const pts=[];
    for(let i=0;i<n*2;i++){const a=-Math.PI/2+i*Math.PI/n, rr=i%2?ri:R; pts.push(cx+rr*Math.cos(a),cy+rr*Math.sin(a));}
    return pts;
  }
