  const tulip=(x,y,s=1)=>T(x,y,s,[p('M0 0 L0 60','n'),p('M0 45 Q-20 30 -24 14 Q-6 22 0 40 Z'),p('M-16 -30 L-8 -18 L0 -32 L8 -18 L16 -30 Q20 0 0 4 Q-20 0 -16 -30 Z')]);
